@php($kinds=['person'=>'Kişi','company'=>'Kurum'])
<section class="directory-list"><div class="row"><h2>Kişiler ve kurumlar</h2><small>{{$records->total()}} kayıt</small></div><div class="scroll"><table><thead><tr><th>Ad / unvan</th><th>Tür</th><th>Cari bakiye</th><th>İletişim</th><th></th></tr></thead><tbody>@forelse($records as $record)<tr><td><a class="contact-name" href="/muhasebe?contact_id={{$record->id}}"><span class="contact-avatar">{{mb_substr($record->name,0,1)}}</span><b>{{$record->name}}</b></a><div class="account-due-alerts">@foreach($record->due_alerts as $key=>$alert)@php([$urgency,$entryType]=explode(':',$key))<a class="account-due-alert {{$urgency}}" href="/muhasebe?contact_id={{$record->id}}&amp;status={{$urgency==='overdue'?'overdue':'open'}}&amp;type={{$entryType}}" title="En erken vade: {{\Carbon\Carbon::parse($alert['date'])->format('d.m.Y')}}">{{$urgency==='overdue'?'!':'◷'}} {{$alert['count']}} {{$urgency==='overdue'?'geciken':'yaklaşan'}} {{$entryType==='receivable'?'alacak':'ödeme'}}</a>@endforeach</div><div class="tag-list">@foreach(json_decode($record->tags ?? '[]',true) as $tag)<span class="record-tag contact-tag">{{$tag}}</span>@endforeach</div></td><td><span class="directory-badge">{{$kinds[$record->kind]}}</span></td><td class="contact-balance">@if($record->has_open_balance)@foreach($record->balances as $balance)@php($net=(int)$balance->receivable-(int)$balance->debt)@if((int)$balance->receivable>0 || (int)$balance->debt>0)<div class="balance-line">@if($net!=0)<strong class="{{$net>0?'positive':'negative'}}">{{number_format(abs($net)/10000,2,',','.')}} {{$balance->currency==='XAU'?'gr':$balance->currency}}</strong><small>{{$net>0?'Alacak':'Borç'}}</small>@else<small>{{$balance->currency}} · Net bakiye sıfır (açık işlemler var)</small>@endif</div>@endif@endforeach @else<span class="settled-balance">Hesap kapalı</span>@endif</td><td class="contact-info">{{$record->email ?: '—'}}<br><small>{{$record->phone}}</small></td><td class="contact-actions"><a class="row-action" href="/muhasebe?contact_id={{$record->id}}">Hesabı aç</a> <a class="row-action" href="/muhasebe/rehber/{{$record->id}}/duzenle">Düzenle</a> <a class="row-action" href="/muhasebe?directory_id={{$record->id}}#new">＋ İşlem ekle</a></td></tr>@empty<tr><td colspan="5"><b>{{request('q') ? 'Aramanızla eşleşen kayıt yok.' : 'Rehberiniz henüz boş.'}}</b><p>Yeni kayıt ekleyin; işlem girerken tekrar kullanın.</p><a class="button" href="/muhasebe/rehber/ekle">＋ İlk kaydı ekle</a></td></tr>@endforelse</tbody></table></div><div class="row directory-pagination" style="margin-top:20px">@if($records->previousPageUrl())<a href="{{$records->previousPageUrl()}}">← Önceki</a>@endif<small>Sayfa {{$records->currentPage()}} / {{$records->lastPage()}}</small>@if($records->nextPageUrl())<a href="{{$records->nextPageUrl()}}">Sonraki →</a>@endif</div></section>
<section class="general-account-total"><div class="row"><h2>Genel cari toplam</h2><small>Tüm hesaplar · Arama ve sayfalamadan bağımsız</small></div><table><tbody>@forelse($generalBalances as $currency=>$balance)@php($net=$balance['receivable']-$balance['debt'])<tr><th scope="row">{{$currency==='XAU'?'Gram altın':($currency==='TRY'?'TL':$currency)}}</th><td>@if($net!=0)<span>{{$net>0?'Net alacak':'Net borç'}}</span> <strong class="{{$net>0?'positive':'negative'}}">{{number_format(abs($net)/10000,2,',','.')}}</strong>@else<span class="settled-balance">{{$balance['receivable']==0 && $balance['debt']==0?'Hesaplar kapalı':'Net bakiye sıfır'}}</span>@endif</td></tr>@empty<tr><td colspan="2" class="settled-balance">Henüz cari hareket bulunmuyor.</td></tr>@endforelse</tbody></table></section>
